QDA with covariances shrunk 40% toward the pooled one reaches 0.834 leave-one-out versus 0.787 for LDA, so I will build QDA into the net. The net can hold about 46 squared directions (silu(z)+silu(-z) is about z^2/2 for small z), so I test how much QDA survives when each class's quadratic term (minus a reference) keeps only its largest eigen-directions.
```python
import numpy as np
X=np.load("train_x.npy"); y=np.load("train_y.npy")
def qda(X,y,a=0.4):
    mu=np.array([X[y==c].mean(0) for c in range(4)])
    Sp=sum(((X[y==c]-mu[c]).T@(X[y==c]-mu[c])) for c in range(4))/(len(X)-4)
    out=[]
    for c in range(4):
        D=X[y==c]-mu[c]; S=0.6*Sp+0.4*D.T@D/(len(D)-1)
        Si=np.linalg.inv(S); out.append((Si, Si@mu[c], -0.5*mu[c]@Si@mu[c]-0.5*np.linalg.slogdet(S)[1]))
    return Sp,out
def build(X,y,K,ref):
    Sp,P=qda(X,y)
    L=np.linalg.cholesky(Sp)
    Qs=[Si for Si,_,_ in P]
    R=np.mean(Qs,0) if ref=='mean' else Qs[ref]
    ev=[]
    for c in range(4):
        Du=L.T@(Qs[c]-R)@L
        w,V=np.linalg.eigh(Du)
        for j in range(18):
            if abs(w[j])>1e-9: ev.append((abs(w[j]),c,w[j],np.linalg.solve(L.T,V[:,j])))  # direction in x-space: t = v.x with u-coords
    ev.sort(key=lambda e:-e[0]); ev=ev[:K]
    def score(Xn):
        s=np.stack([Xn@P[c][1]+P[c][2] for c in range(4)],1)
        for _,c,lam,v in ev: s[:,c]+=-0.5*lam*(Xn@v)**2
        return s
    return score,len(ev)
def cv(K,ref,folds=10):
    idx=np.arange(len(X)); ok=0
    for f in range(folds):
        te=idx%folds==f
        sc,_=build(X[~te],y[~te],K,ref); ok+=(sc(X[te]).argmax(1)==y[te]).sum()
    return ok/len(X)
for ref in ['mean',0,1,2,3]:
    for K in [24,36,46,54,72]:
        sc,n=build(X,y,K,ref)
        print(ref,K,n,round((sc(X).argmax(1)==y).mean(),3),round(cv(K,ref),3))
```

