Keeping only 24 squared directions with class 1 or 2 as reference keeps QDA's 0.92 train and about 0.81 10-fold, so the whole quadratic fits in layer 1 as 24 silu pairs. Now I pick the shrink amount by 10-fold and compare with LDA on the same folds.
```python
import numpy as np
X=np.load("train_x.npy"); y=np.load("train_y.npy")
def build(X,y,K,ref,a):
    mu=np.array([X[y==c].mean(0) for c in range(4)])
    Sp=sum(((X[y==c]-mu[c]).T@(X[y==c]-mu[c])) for c in range(4))/(len(X)-4)
    P=[]
    for c in range(4):
        D=X[y==c]-mu[c]; S=(1-a)*Sp+a*D.T@D/(len(D)-1)
        Si=np.linalg.inv(S); P.append((Si, Si@mu[c], -0.5*mu[c]@Si@mu[c]-0.5*np.linalg.slogdet(S)[1]))
    L=np.linalg.cholesky(Sp); R=P[ref][0]; ev=[]
    for c in range(4):
        w,V=np.linalg.eigh(L.T@(P[c][0]-R)@L)
        for j in range(18):
            if abs(w[j])>1e-9: ev.append((abs(w[j]),c,w[j],np.linalg.solve(L.T,V[:,j])))
    ev.sort(key=lambda e:-e[0]); ev=ev[:K]
    def score(Xn):
        s=np.stack([Xn@P[c][1]+P[c][2] for c in range(4)],1)
        for _,c,lam,v in ev: s[:,c]+=-0.5*lam*(Xn@v)**2
        return s
    return score
def cv(K,ref,a,folds=10,off=0):
    idx=(np.arange(len(X))*7+off)%len(X); ok=0
    for f in range(folds):
        te=idx%folds==f
        sc=build(X[~te],y[~te],K,ref,a); ok+=(sc(X[te]).argmax(1)==y[te]).sum()
    return ok/len(X)
for a in [0,0.2,0.4,0.6,0.8]:
    for ref in [1,2]:
        print(a,ref,[round(np.mean([cv(K,ref,a,off=o) for o in range(3)]),3) for K in [18,24,30]])
